import {editMeshRegion,validateMeshRegionContours} from './mesh-region.js';
import {directedMeshEdges,boundaryPaths} from './mesh-boundaries.js';

const subtract=(a,b)=>a.map((v,i)=>v-b[i]),dot=(a,b)=>a.reduce((s,v,i)=>s+v*b[i],0),cross=(a,b)=>[a[1]*b[2]-a[2]*b[1],a[2]*b[0]-a[0]*b[2],a[0]*b[1]-a[1]*b[0]],unit=a=>{const length=Math.hypot(...a);if(!length)throw Error('넓이가 없는 영역이에요.');return a.map(v=>v/length);};
export function bevelMeshRegion(data,{operation,faces=[],distance=.1,height=.1,segments=1,profile='linear'}={}){
 if(operation!=='bevelRegion')return null;
 if(!Array.isArray(data?.vertices)||!Array.isArray(data?.indices)||!Array.isArray(faces)||!faces.length||faces.some(f=>!Number.isInteger(f)||f<0||f>=data.indices.length/3)||!Number.isFinite(distance)||distance<=0||distance>1000000||!Number.isFinite(height)||!height||Math.abs(height)>1000000||!Number.isInteger(segments)||segments<1||segments>64||!['linear','round'].includes(profile))throw Error('평면 베벨의 면·양의 폭·높이·분할1~64·프로파일을 확인하세요.');
 const selected=new Set(faces),paths=boundaryPaths([...directedMeshEdges(data,selected).values()].filter(e=>e.count===1)),count=paths.reduce((sum,p)=>sum+p.ids.length,0);
 if(data.vertices.length+count*segments>1000000)throw Error('베벨 결과의 정점 예산을 넘었어요. 영역을 나눠 편집하세요.');
 // Existing region validation/offset, holes, cap triangulation and endpoint
 // barycentric attributes are reused exactly once; the new rim replaces its band.
 const result=editMeshRegion(data,{operation:'insetRegion',faces,distance});if(result.indices.length+count*6*(segments-1)>6000000)throw Error('베벨 결과의 삼각형 예산을 넘었어요. 영역을 나눠 편집하세요.');if(result.vertices.length!==data.vertices.length+count)throw Error('베벨 경계 정점 연결을 확인하세요.');
 const tri=data.indices.slice(faces[0]*3,faces[0]*3+3).map(i=>data.vertices[i]),origin=tri[0],u=unit(subtract(tri[1],origin)),normal=unit(cross(subtract(tri[1],origin),subtract(tri[2],origin))),v=cross(normal,u),project=p=>{const q=subtract(p,origin);return[dot(q,u),dot(q,v)];},budget={checks:0};let next=data.vertices.length;
 const loops=paths.map(path=>path.ids.map(outside=>{const inside=next++;return{outside,inside,point:[...result.vertices[inside]]};}));result.indices.length-=count*6;const caps=result.indices.length;
 let previous=loops.map(loop=>loop.map(row=>row.outside));
 for(let step=1;step<=segments;step++){
  const t=step/segments,inset=profile==='round'?1-Math.cos(t*Math.PI/2):t,rise=profile==='round'?Math.sin(t*Math.PI/2):t,ring=loops.map(loop=>loop.map(row=>{const a=data.vertices[row.outside],position=a.map((value,k)=>value+(row.point[k]-value)*inset+normal[k]*height*rise);if(step===segments){result.vertices[row.inside]=position;return row.inside;}const id=result.vertices.length;result.vertices.push(position);for(const field of ['uvs','uvs1','colors'])if(result[field])result[field].push(data[field][row.outside].map((value,k)=>value+(result[field][row.inside][k]-value)*inset));return id;}));
  validateMeshRegionContours(ring.map(loop=>loop.map(id=>project(result.vertices[id]))),budget);
  for(let l=0;l<ring.length;l++)for(let i=0;i<ring[l].length;i++){const j=(i+1)%ring[l].length,a=previous[l][i],b=previous[l][j],c=ring[l][j],d=ring[l][i];result.indices.push(a,b,c,a,c,d);}previous=ring;
 }
 const before=directedMeshEdges(data),after=directedMeshEdges(result);for(const [key,edge] of directedMeshEdges(data,selected))if(edge.count===1&&after.get(key)?.count!==before.get(key)?.count)throw Error('베벨의 원래 경계가 유지되지 않았어요.');for(const [key,edge]of after)if(!before.has(key)&&edge.count!==2||edge.invalid&&!before.get(key)?.invalid)throw Error('베벨에 열린 간선이나 뒤집힌 연결이 생겼어요.');for(let i=caps;i<result.indices.length;i+=3){const [a,b,c]=result.indices.slice(i,i+3).map(id=>result.vertices[id]);if(!Math.hypot(...cross(subtract(b,a),subtract(c,a))))throw Error('베벨 면이 겹쳤어요. 폭·높이·분할을 조절하세요.');}
 delete result.normals;return result;
}
export const meshRegionBevelContract={command:'world.mesh.edit',settings:{operation:'bevelRegion',faces:'selected coplanar triangle indices',distance:'positive inset width',height:'nonzero signed normal rise',segments:'integer1..64',profile:'linear | round (quarter ellipse)'},geometry:'Existing connected planar region inset/cap/hole validation once, ring replacement with chamfer/round profile; original boundary identities/unselected faces retained. Inner cap uses existing barycentric attributes, rim linearly interpolates UV0/UV1/colors between boundary endpoints. Shared directed topology/degenerate/contour checks.',authoring:'Typed width/height/segments/profile and one existing Undo/CAS/dryRun/save; existing mesh loader/render/collider data format, no new runtime worker/GPU/SDK transport.',cost:'Full existing mesh clone/validation, initial offset/triangulation and bounded contour comparisons remain; boundary*segments vertices and triangles preflight against existing mesh budgets. Not a runtime/FPS improvement.',limits:'Planar region relief bevel only, not arbitrary curved-edge solid chamfer, automatic edge loops or global collision/self-intersection with unrelated faces; sharp-normal/material-seam policy and full DCC quality remain separate. No GUI/backend pixels/device claim.'};
